window.kbPageData["views/entry/k-57dd40cabf9b2c29"] = {"key":"entry/k-57dd40cabf9b2c29","state":{"route":"entry/k-57dd40cabf9b2c29"},"node":{"id":"k-57dd40cabf9b2c29","mode":"k","title":"溶质质量分数","type":"概念与词义","domain":"数学","reading":"","intro":"","priority":100,"aliases":["溶液质量浓度等于溶质质量除以溶液质量","溶液质量分数等于溶质质量除以溶液总质量"],"qs":["江苏 2025 A类 行测#63","江苏 2025 C类 行测#63"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":1,"directorySummary":"溶质质量分数等于溶质质量除以溶液总质量。本题以质量百分比表示酒精溶液的浓度。","review":{"definition":"溶质质量分数等于溶质质量除以溶液总质量。本题以质量百分比表示酒精溶液的浓度。","explanation":"甲瓶先加20克水，再加30克纯酒精，恢复到原浓度，说明净加入的50克中，酒精所占比例与原溶液相同，故原浓度为30÷50=60%。设每瓶原有 m 克。甲瓶只加水时浓度为0.6m/(m+20)，乙瓶加50克30%的酒精溶液后浓度为(0.6m+15)/(m+50)。两式相等，得到 m=100。","references":[],"evidence":"若继续在甲瓶中加入30克纯酒精，溶液又恢复到最初浓度","disposition":"独立词条","basis":"据原题和解析编释。","title":"溶质质量分数","related":[],"examFocus":{"江苏 2025 A类 行测#63":"用溶质质量分数表示两瓶加料后的浓度，分别利用甲瓶加纯酒精后恢复原浓度和两瓶第一次加料后浓度相等的条件。"}},"readings":[{"origin":"k-57dd40cabf9b2c29","title":"溶质质量分数","qs":["江苏 2025 C类 行测#63"],"definition":"溶质质量分数等于溶质质量除以溶液总质量。本题以质量百分比表示酒精溶液的浓度。","explanation":"甲瓶先加20克水，再加30克纯酒精，恢复到原浓度，说明净加入的50克中，酒精所占比例与原溶液相同，故原浓度为30÷50=60%。设每瓶原有 m 克。甲瓶只加水时浓度为0.6m/(m+20)，乙瓶加50克30%的酒精溶液后浓度为(0.6m+15)/(m+50)。两式相等，得到 m=100。","evidence":"若继续在甲瓶中加入30克纯酒精，溶液又恢复到最初浓度","doubt":"","references":[]},{"origin":"k-820539a9a0028374","title":"溶质质量分数","qs":["江苏 2025 A类 行测#63"],"definition":"溶质质量分数是溶质质量占溶液总质量的比例，通常用百分数表示。","explanation":"本题按质量分数计算酒精浓度。设两瓶初始质量均为 m 克、浓度均为 n。甲瓶前后共加入 50 克液体，其中酒精 30 克，恢复原浓度意味着 (mn＋30)÷(m＋50)＝n，得到 n＝60%。第一次加液时，甲瓶只加水，酒精仍为 0.6m 克。乙瓶加入的 50 克溶液含 15 克酒精。两瓶此时浓度相等，故 0.6m÷(m＋20)＝(0.6m＋15)÷(m＋50)，解得 m＝100，选 A。","evidence":"50克浓度为30%的酒精溶液","doubt":"","references":[]}]},"questions":{"江苏 2025 A类 行测#63":{"paper":"江苏 2025 A类 行测","n":63,"mod":"数量关系","src":["98687766ac277f427cd6.pdf",13],"asrc":["4fe8e0544dd7b47699d2.pdf",19],"card":"d34c43b675ff40c91f0a1466","links":[{"id":"k-57dd40cabf9b2c29","role":"解题依据","why":"需要根据质量分数求加入溶液中的酒精质量，并用酒精质量与溶液总质量之比表示加料后的浓度。"}]},"江苏 2025 C类 行测#63":{"paper":"江苏 2025 C类 行测","n":63,"mod":"数量关系","src":["ffc394a1c160f331ec57.pdf",14],"asrc":["d1de3b437151c05b769e.pdf",18],"card":"f54d5d677609c366b52ddc4f","links":[{"id":"k-57dd40cabf9b2c29","role":"解题依据","why":"各次操作后的浓度由当时的酒精质量和溶液总质量确定。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-57dd40cabf9b2c29":[["江苏 2025 A类 行测#63","江苏 2025 C类 行测#63"]]}};
